cpp.setup:
auto* control = new fluent::layout::Expander(%PARENT%);
control->setHeaderText(QStringLiteral("Advanced options"));
auto* body = new QWidget(control);
auto* bodyLayout = new QVBoxLayout(body);
bodyLayout->setContentsMargins(16, 12, 16, 14);
auto* detail = new fluent::textfields::Label(QStringLiteral("Enable background telemetry sync"), body);
detail->setWordWrap(true);
bodyLayout->addWidget(detail);
control->setContentWidget(body, fluent::WidgetOwnership::Owned);
control->setExpandedAnimated(true, false);
